import java.util.*;
public class Dbg {
    public static void main(String[] args) {
        TimeZone GMT = TimeZone.getTimeZone("GMT");
        TimeZone INDIA = TimeZone.getTimeZone("GMT+05:30");
        Calendar cal = Calendar.getInstance(GMT, Locale.US);
        cal.clear();
        cal.set(2021, Calendar.JANUARY, 1, 0, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        System.out.println("before millis=" + cal.getTimeInMillis());
        Calendar clone = (Calendar) cal.clone();
        clone.setTimeZone(INDIA);
        System.out.println("after millis=" + clone.getTimeInMillis());
        System.out.println("hour=" + clone.get(Calendar.HOUR_OF_DAY) + " min=" + clone.get(Calendar.MINUTE));
    }
}
